{"path":"assets/css/styles.css","content":"/* Base styles for the practice site */
:root{
  --bg:#fbfdff; --muted:#6b7280; --accent:#2563eb; --soft:#f8fafc; --card:#ffffff;
  --radius:12px; --maxw:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#0f172a}
.page-pattern{position:fixed; inset:0; width:100%; height:100%; z-index:-1; opacity:0.8}
.wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
.brand h1{margin:0;font-size:18px;letter-spacing:0.2px}
.brand .tagline{margin:2px 0 0;font-size:13px;color:var(--muted)}
.main-nav a{margin-left:14px;color:#0b1220;text-decoration:none;font-size:14px}
.main-nav a.pill{background:#fff;border-radius:999px;padding:8px 12px;box-shadow:0 1px 4px rgba(12,20,40,0.04)}
.hero{padding:40px 0}
.hero-inner{display:flex;gap:24px;align-items:center;justify-content:space-between;max-width:var(--maxw);margin:0 auto}
.hero-copy{flex:1}
.hero-copy h2{margin:0 0 10px;font-size:28px}
.lead{color:var(--muted);margin:0 0 18px}
.mood-module{background:var(--card);padding:14px;border-radius:10px;box-shadow:0 6px 18px rgba(11,20,40,0.04);max-width:520px}
.mood-label{display:block;font-weight:600;margin-bottom:8px}
.mood-options{display:flex;gap:8px;flex-wrap:wrap}
.mood-btn{background:#f1f5f9;border:1px solid #e6eef8;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood-btn:focus{outline:3px solid rgba(37,99,235,0.15)}
.mood-recommendation{margin-top:12px}
.primary-cta{display:inline-block;margin-top:10px;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
.primary-cta.big{font-size:18px;padding:12px 18px}
.hero-visual{width:320px}
.diagnostic{background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.98));padding:28px 0}
.accordion{margin-top:12px;border-radius:10px}
.accordion-toggle{width:100%;text-align:left;padding:12px;border:1px solid #eef2ff;background:#fff;border-radius:10px;cursor:pointer}
.accordion-panel{padding:12px;border-left:1px solid #eef2ff;border-right:1px solid #eef2ff;border-bottom:1px solid #eef2ff}
.plan{padding:28px 0}
.plans-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:12px}
.plan-card{background:var(--card);padding:14px;border-radius:10px;border:1px solid #f1f5f9}
.plan-card h3{margin:0 0 6px}
.plan-cta{display:inline-block;margin-top:8px;color:var(--accent)}
.micro_habits{padding:18px 0;background:#fff}
.habits{list-style:disc;margin-left:20px;color:var(--muted)}
.pricing{padding:28px 0}
.pricing-grid{display:flex;gap:12px}
.price-item{background:#fff;padding:12px;border-radius:10px;border:1px solid #f0f4ff}
.cta-block{padding:24px 0;text-align:center}
.site-footer{background:transparent;padding:24px 28px;border-top:1px solid #eef2ff;margin-top:20px}
.footer-grid{display:flex;gap:20px;align-items:flex-start;justify-content:space-between}
.muted{color:var(--muted);font-size:13px}
.muted-small{color:var(--muted);font-size:12px}
.copyline{text-align:center;color:var(--muted);font-size:12px;margin-top:12px}
@media(max-width:820px){
  .hero-inner{flex-direction:column}
  .hero-visual{display:none}
  .footer-grid{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mood-to-Method selector
  var moodMap = {
    overwhelmed: {
      title: 'Stability Planning',
      desc: 'Short sequence to reduce reactivity, create immediate safety plans, and set reachable next steps.',
      cta: 'Request a Stability Session',
      urlSuffix: '#stability'
    },
    stuck: {
      title: 'Focused Exploration',
      desc: 'Targeted sessions to unpack what blocks movement and rehearse alternative responses.',
      cta: 'Start Focused Exploration',
      urlSuffix: '#explore'
    },
    numb: {
      title: 'Mindful Reset',
      desc: 'Gentle pacing to re-engage sensation, values, and small behavioral experiments.',
      cta: 'Try a Mindful Reset',
      urlSuffix: '#reset'
    },
    anxious: {
      title: 'Containment Session',
      desc: 'Practical tools for managing anxiety in the short term and mapping triggers over time.',
      cta: 'Book a Containment Session',
      urlSuffix: '#contain'
    },
    sad: {
      title: 'Companion Track',
      desc: 'Support for low mood with emphasis on pacing, activation, and compassionate reflection.',
      cta: 'Begin Companion Track',
      urlSuffix: '#companion'
    },
    curious: {
      title: 'Starter Track',
      desc: 'A focused intake and planning phase to clarify goals and the best match of work.',
      cta: 'Schedule an Intake',
      urlSuffix: '#intake'
    }
  };

  function $(sel){return document.querySelector(sel)}
  function $all(sel){return Array.prototype.slice.call(document.querySelectorAll(sel))}

  var moodBtns = $all('.mood-btn');
  var titleEl = $('#method-title');
  var descEl = $('#method-desc');
  var ctaEl = $('#primary-cta');

  moodBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      var mood = btn.getAttribute('data-mood');
      var info = moodMap[mood];
      if(!info) return;
      titleEl.textContent = info.title;
      descEl.textContent = info.desc;
      // update CTA text but preserve base url if provided
      var baseUrl = ctaEl.getAttribute('data-base') || ctaEl.getAttribute('href') || '#';
      ctaEl.textContent = info.cta;
      // attempt to set a friendly hash so forms can prefill if needed
      ctaEl.setAttribute('href', (baseUrl.split('#')[0] || baseUrl) + info.urlSuffix);

      // highlight selected
      moodBtns.forEach(function(b){b.classList.remove('active')});
      btn.classList.add('active');
    });
  });

  // Accessibility: set data-base to preserve original
  (function(){ if(ctaEl) ctaEl.setAttribute('data-base', ctaEl.getAttribute('href') || '#'); })();

  // Accordion for confidentiality/session boundaries (multiple instances)
  var accs = $all('[data-accordion]');
  accs.forEach(function(root){
    var btn = root.querySelector('.accordion-toggle');
    var panel = root.querySelector('.accordion-panel');
    if(!btn || !panel) return;
    btn.addEventListener('click', function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!expanded));
      if(expanded){ panel.hidden = true; }
      else{ panel.hidden = false; panel.focus(); }
    });
  });

  // Footer year
  var y = new Date().getFullYear();
  var yearEl = document.getElementById('year');
  if(yearEl) yearEl.textContent = y;

  // Respectful crisis footer: ensure visible on critical panels
  var crisisLines = document.querySelectorAll('.muted');
  crisisLines.forEach(function(el){
    // no-op but ensures code touches them for future enhancements
    el.setAttribute('data-safe','true');
  });

})();
"} 
